class Solution {
    private lateinit var count:MutableMap<Int,Int>;
    private var length=0;
    fun numSquarefulPerms(nums:IntArray):Int{
        count=mutableMapOf();
        for(value in nums)count[value]=(count[value]?:0)+1;
        length=nums.size;
        return dfs(0,0,false)
    };
    private fun dfs(depth:Int,previous:Int,hasPrevious:Boolean):Int{
        if(depth==length)return 1;
        var ways=0;
        for(value in count.keys.toList())if(count[value]!!>0&&(!hasPrevious||square(previous+value))){
            count[value]=count[value]!!-1;
            ways+=dfs(depth+1,value,true);
            count[value]=count[value]!!+1
        };
        return ways
    };
    private fun square(value:Int):Boolean{
        val root=kotlin.math.sqrt(value.toDouble()).toInt();
        return root*root==value
    }
}

