class Solution {
    unordered_map<int,int> count;
    int length;
    bool square(int value){
        int root=sqrt(value);
        return root*root==value;
    }
    int dfs(int depth,int previous,bool hasPrevious){
        if(depth==length)return 1;
        int ways=0;
        for(auto& entry:count){
            int value=entry.first;
            if(entry.second>0&&(!hasPrevious||square(previous+value))){
                --entry.second;
                ways+=dfs(depth+1,value,true);
                ++entry.second;
            }
        }
        return ways;
    }
    public:int numSquarefulPerms(vector<int>& nums){
        for(int value:nums)++count[value];
        length=nums.size();
        return dfs(0,0,false);
    }
};
